return ['domain'=>'jeytech-order-transfer-qr','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'JeyTech Order Transfer QR 1.0.0','pot-creation-date'=>'2026-09-27 21:30+0200','po-revision-date'=>'2026-09-27 21:30+0200','messages'=>['A BIC is required for a beneficiary outside the EEA.'=>'Un BIC est nécessaire pour un bénéficiaire situé hors de l’EEE.','A SEPA QR with the exact amount and order reference, generated on your own site.'=>'Un QR SEPA avec le montant exact et la référence de commande, généré sur votre site.','Add a locally generated SEPA QR to unpaid bank transfer orders, with the amount and order reference filled in.'=>'Ajoute un QR SEPA généré localement aux commandes impayées par virement, avec le montant et la référence préremplis.','Amount'=>'Montant','Bank account checks'=>'Contrôle des comptes bancaires','Banking app support varies. Test the QR with the banks your customers use. The customer must verify the beneficiary, amount and reference before confirming.'=>'La prise en charge dépend de l’application bancaire. Testez le QR avec les banques de vos clients. Le client doit vérifier le bénéficiaire, le montant et la référence avant de confirmer.','Before using it'=>'Avant de l’utiliser','Beneficiary'=>'Bénéficiaire','Beneficiary account'=>'Compte bénéficiaire','Choose a WooCommerce bank account'=>'Choisissez un compte bancaire WooCommerce','Choose the account explicitly. Reordering accounts keeps your selection; changing the beneficiary, IBAN or BIC requires a new selection.'=>'Choisissez explicitement le compte. Réordonner les comptes conserve votre sélection ; modifier le bénéficiaire, l’IBAN ou le BIC nécessite de sélectionner à nouveau le compte.','Customer on-hold email'=>'E-mail client de commande en attente','Edit bank accounts in WooCommerce'=>'Modifier les comptes bancaires dans WooCommerce','Enable QR codes for unpaid bank transfer orders in EUR'=>'Activer les QR pour les commandes impayées par virement en EUR','Enabled'=>'Activé','Enter a valid IBAN from a SEPA country in the WooCommerce bank transfer settings.'=>'Saisissez un IBAN valide d’un pays SEPA dans les réglages de virement WooCommerce.','Enter these details in your banking app and check them before confirming the transfer.'=>'Saisissez ces coordonnées dans votre application bancaire et vérifiez-les avant de confirmer le virement.','Example only: EUR 19.90, reference DEMO-1042 with your format. Do not confirm this transfer.'=>'Exemple uniquement : 19,90 EUR, référence DEMO-1042 selon votre format. Ne confirmez pas ce virement.','Image links expire after 30 days and stop working if the order is paid, cancelled, changed or the selected bank account changes. Existing copies cached by email providers cannot be revoked.'=>'Les liens d’image expirent après 30 jours et cessent de fonctionner si la commande est payée, annulée ou modifiée, ou si le compte bancaire choisi change. Les copies déjà mises en cache par les services de messagerie ne peuvent pas être révoquées.','JeyTech'=>'JeyTech','JeyTech Order Transfer QR for WooCommerce'=>'JeyTech Order Transfer QR for WooCommerce','JeyTech Order Transfer QR for WooCommerce needs WooCommerce %s or later to run.'=>'JeyTech Order Transfer QR for WooCommerce nécessite WooCommerce %s ou ultérieur.','JeyTech Order Transfer QR needs the PHP zlib extension to generate PNG images.'=>'JeyTech Order Transfer QR nécessite l’extension PHP zlib pour générer les images PNG.','Keep {order_number}. Example: SHOP-{order_number}. The final reference is limited to 140 characters and the full QR payload to 331 bytes.'=>'Conservez {order_number}. Exemple : BOUTIQUE-{order_number}. La référence finale est limitée à 140 caractères et l’ensemble des données du QR à 331 octets.','No bank account found. Add your beneficiary name, IBAN and BIC in WooCommerce first.'=>'Aucun compte bancaire trouvé. Ajoutez d’abord le nom du bénéficiaire, l’IBAN et le BIC dans WooCommerce.','Only on-hold BACS orders in EUR receive a QR. It prepares a transfer and never marks an order as paid.'=>'Seules les commandes BACS en attente et en EUR reçoivent un QR. Il prépare le virement et ne marque jamais une commande comme payée.','Order confirmation page'=>'Page de confirmation de commande','Pay by bank transfer'=>'Payer par virement','Payment configuration'=>'Configuration du paiement','Payment reference format'=>'Format de la référence de paiement','Plain-text emails keep the bank details and reference, without an image. No additional email is sent.'=>'Les e-mails en texte brut conservent les coordonnées bancaires et la référence, sans image. Aucun e-mail supplémentaire n’est envoyé.','Reference'=>'Référence','SEPA bank transfer QR'=>'QR de virement SEPA','Sample QR'=>'Exemple de QR','Sample SEPA QR, not a real order'=>'Exemple de QR SEPA, sans commande réelle','Save changes'=>'Enregistrer les modifications','Scan this QR with a banking app that supports EPC / GiroCode, then check the details before confirming the transfer.'=>'Scannez ce QR avec une application bancaire compatible EPC / GiroCode, puis vérifiez les coordonnées avant de confirmer le virement.','Select a bank account before enabling QR codes.'=>'Choisissez un compte bancaire avant d’activer les QR.','Settings'=>'Réglages','Setup required or disabled'=>'À configurer ou désactivé','The BIC must contain 8 or 11 characters.'=>'Le BIC doit contenir 8 ou 11 caractères.','The amount must be between EUR 0.01 and EUR 999999999.99.'=>'Le montant doit être compris entre 0,01 EUR et 999 999 999,99 EUR.','The beneficiary name must contain 1 to 70 characters on one line.'=>'Le nom du bénéficiaire doit contenir de 1 à 70 caractères sur une seule ligne.','The order total must be an exact euro amount with at most two decimal places.'=>'Le total de la commande doit être un montant exact en euros avec au plus deux décimales.','The payment data exceeds the 331-byte EPC limit. Shorten the reference format.'=>'Les données de paiement dépassent la limite EPC de 331 octets. Raccourcissez le format de référence.','The payment reference must contain 1 to 140 characters on one line.'=>'La référence de paiement doit contenir de 1 à 140 caractères sur une seule ligne.','Use a single-line reference format with {order_number}, up to 140 characters. Other placeholders are not supported.'=>'Utilisez un format de référence sur une seule ligne contenant {order_number}, limité à 140 caractères. Les autres variables ne sont pas prises en charge.','Valid IBAN and beneficiary details'=>'IBAN et coordonnées du bénéficiaire valides','Where to display it'=>'Emplacements d’affichage','You can also enter these details manually. This QR prepares the transfer; it does not confirm payment or change the order status.'=>'Vous pouvez aussi saisir ces coordonnées manuellement. Ce QR prépare le virement ; il ne confirme pas le paiement et ne modifie pas l’état de la commande.','https://jeytech.app'=>'https://jeytech.app','Bank'=>'Banque','Account number'=>'Numéro de compte','Sort code'=>'Code bancaire']];